        ]
      ,
      "budget_share": 0.4
      ,
      "why": "Smallest datapath (1 micro-rotation/cycle, barrel shifters); N+3 cycles/result means it likely cannot reach 50 MSPS, but worth a cheap probe to confirm feasibility and to bound the area floor."
      }
    ],
    "rationale": "Probe both unexplored families across the accuracy-feasible width/iteration region; keep the pipelined_m point as seed. If neither clears 50 MSPS, next round map the front over pipelined/pipelined_m full ranges."
  }
}

